import { crm, loose } from adapters
db = connect crm
free = connect loose

node Company: "each company named" {
  name: <text> "its name"
}

function scan(x: <db-[:company]->>) {
  x-[n:notes]-> {
    delete n
  }
  v = "Acme"
  delete v
  people = x-[:people]->
  delete people
  w = x.name == "a" ? x : null
  delete w
  d = extract from [x.name] {
    node co: "a company" {
      nm: <text> "the name"
    }
  }
  delete d
  d-[k:co]-> {
    delete k
  }
  delete x
}

