import { slack, loose } from adapters
import { vc_url_retrieval, linkedin_enrichment } from plugins
chat = slack()
free = loose()
movement scan(c: <chat-[:channel]->>, d: <chat-[:channel]->-[:#members]->>) {
  x1 = FIRST(c-[:#foo]->)
  x2 = c-[:#foo]->.Name
  c-[:#foo]-> {
    y = 1
  }
  c-[#foo]-> {
    y = 1
  }
  x3 = c-[:`#foo`]->.Name
  write c-[:#foo]-> { Body: "a" }
  x4 = COUNT(chat-[:#Channels]->)
  x5 = FIRST(free-[:#foo]->)
  c-[f:#resources]-> {
    y = f.url
  }
  x6 = c-[t:#transform { plugin: "vc_url_retrieval" }]->.out
  x7 = c-[t:#transform { plugin: "linkedin_enrichment" }]->.out
  x8 = c-[#linked WHERE type = "ATTIO"]->.external_id
  x9 = c-[t:#transform]->.out
}
listen to chat fire scan

